const t = (x: any) => x.kind === "foreground" ? (x.stdout.text + (x.stderr.text || "")) : JSON.stringify(x);
const [job, procs] = await Promise.all([
  tools.job_output({ job_id: "pwsh-107", wait: true, timeout_ms: 180000 }),
  tools.pwsh({ command: `Get-Process | Where-Object { $_.ProcessName -match 'chrome|agent-browser' } | Select-Object -First 8 Id,ProcessName | Format-Table -AutoSize | Out-String -Width 150`, description: "Check browser processes running" }),
]);
console.log("### JOB\n" + t(job).slice(0, 9000));
console.log("\n### PROCS\n" + t(procs).slice(0, 1200));
